INSERT INTO DimCompany (SK_CompanyID, CompanyID, Status, Name, Industry, SPrating, isLowGrade, CEO, Description, FoundingDate, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, IsCurrent, BatchID, EffectiveDate, EndDate) SELECT CAST(ROW_NUMBER() OVER (ORDER BY c.CompanyID, c.EffectiveDate) AS INT) AS SK_CompanyID, CAST(CompanyID AS INT) AS CompanyID, CAST(Status AS TEXT) AS Status, CAST(Name AS TEXT) AS Name, CAST(Industry AS TEXT) AS Industry, CAST(SPrating AS TEXT) AS SPrating, CAST(isLowGrade AS BOOLEAN) AS isLowGrade, CAST(CEO AS TEXT) AS CEO, CAST(Description AS TEXT) AS Description, CAST(FoundingDate AS DATE) AS FoundingDate, CAST(AddressLine1 AS TEXT) AS AddressLine1, CAST(AddressLine2 AS TEXT) AS AddressLine2, CAST(PostalCode AS TEXT) AS PostalCode, CAST(City AS TEXT) AS City, CAST(StateProv AS TEXT) AS StateProv, CAST(Country AS TEXT) AS Country, CAST(CASE WHEN ROW_NUMBER() OVER (PARTITION BY c.CompanyID ORDER BY c.EffectiveDate DESC) = 1 THEN TRUE ELSE FALSE END AS BOOLEAN) AS IsCurrent, CAST(1 AS DECIMAL(5)) AS BatchID, CAST(EffectiveDate AS DATE) AS EffectiveDate, CAST(COALESCE(LEAD(EffectiveDate) OVER (PARTITION BY CompanyID ORDER BY EffectiveDate), CAST('9999-12-31' AS DATE)) AS DATE) AS EndDate FROM (SELECT CAST(CMP.CIK AS INT) AS CompanyID, CAST(CMP.CompanyName AS TEXT) AS Name, CAST(CMP.SPrating AS TEXT) AS SPrating, CAST(CMP.CEOname AS TEXT) AS CEO, CMP.Description AS Description, CAST(STRPTIME(NULLIF(TRIM(CMP.FoundingDate), ''), '%Y%m%d') AS DATE) AS FoundingDate, CAST(CMP.AddrLine1 AS TEXT) AS AddressLine1, CAST(CMP.AddrLine2 AS TEXT) AS AddressLine2, CAST(CMP.PostalCode AS TEXT) AS PostalCode, CMP.City AS City, CMP.StateProvince AS StateProv, CMP.Country AS Country, CAST(S.ST_NAME AS TEXT) AS Status, CAST(I.IN_NAME AS TEXT) AS Industry, CASE WHEN CMP.SPrating IN ('AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-') THEN FALSE ELSE TRUE END AS isLowGrade, NULL AS EffectiveDate FROM Source.FinwireCMP AS CMP, Source.StatusType AS S, Source.Industry AS I WHERE CMP.Status = S.ST_ID AND CMP.IndustryID = I.IN_ID) AS c;
